// Preload for the tsx maintenance scripts (`pnpm db:seed`, …). It never runs
// inside the app.
//
// Server modules the scripts import (auth → registration gate, e-mail copy)
// use Paraglide messages through `#/paraglide/*`. The app's copy in
// `src/paraglide` is generated by the Vite plugin for the dev server: it only
// exists after a Vite/typecheck compile and its runtime reads
// `import.meta.env.SSR`, which does not exist outside Vite. So the scripts
// get their own Node-friendly compile (see `paraglide:scripts` in
// package.json) and this hook points `#/paraglide/*` at it. The shared
// `src/paraglide` folder that running dev servers use is never touched.
import { register } from 'node:module'

register('./script-runtime-hooks.mjs', import.meta.url)
